INSERT INTO `challenges` (`Id`, `Name`, `Description`, `IncompatiblesChallenges`, `ActivationCriterion`, `CompletionCriterion`, `TargetMonsterId`, `CategoryId`) VALUES
(1, 'Zombie', 'Les combattants alliés doivent utiliser exactement un point de mouvement par tour de jeu.\n\nPerdre des points de mouvement en détaclant ne fait pas échouer le challenge.', '2,8,811,805', 'GL>5,0', 'TM=1,0', 0, 1),
(2, 'Statue', 'Les combattants alliés doivent finir leur tour sur la même case que celle où ils l\'ont commencé, pendant toute la durée du combat.', '1,40,971,807,805,813,815,808,37,973,36,39,488,8', 'GL>5,0', 'Tm<1,0', 0, 1),
(3, 'Premier', 'La cible désignée doit être achevée en premier.', '32,10,35,595,34,594,4,25,967', 'GL>5,0&GN>1,1', 'CK~1', 0, 1),
(4, 'Dernier', 'La cible désignée doit être achevée en dernier.', '3,35,32,25,10,594,595,34,967', 'GN>1,1&GL>5,0', 'Ck~1', 0, 1),
(5, 'Économe', 'Les combattants alliés ne doivent utiliser qu\'une seule fois la même action durant toute la durée du combat.', '16,6,7,9,12,14,15,24,41,816,812,810', 'GL>89,0,e&Gl>0.9&Gl<1.25&GN>2,0', 'SAg0', 0, 1),
(6, 'Versatile', 'Les combattants alliés ne doivent utiliser qu\'une seule fois une même action pendant leurs tours de jeu.', '5,14', 'GL>5,0', 'SAt0', 0, 1),
(8, 'Nomade', 'Les combattants alliés doivent utiliser tous leurs points de mouvement à chaque tour pendant toute la durée du combat. ', '1,2,809,811', 'GL>5,0', 'TM=m,0&TT=0,0', 0, 1),
(9, 'Barbare', 'Les personnages alliés doivent achever les ennemis avec une arme.', '5,7,11,15,12,16,22,18', 'GL>40,0&(GC>0,56,t0|GC>0,53,t0|GC>0,55,t0|GC>0,14,t0|GC>0,54,t0|GC>0,469,t0)', 'SK=,e0,e1,c', 0, 1),
(10, 'Cruel', 'Les ennemis doivent êtres achevés dans l\'ordre croissant de leur niveau.', '3,4,594,35,34,32,25,967,595', 'Gd>1,1&GL>5,0', 'SL<1', 0, 1),
(11, 'Mystique des éléments', 'Les combattants alliés ne doivent utiliser que des éléments différents durant leurs tours de jeu.', '9', 'GL>49,0,e', 'SC!hc0,e,t', 0, 1),
(17, 'Intouchable', 'Les alliés ne doivent pas perdre de points de vie ou de bouclier.', '33,49,487,976,47', 'GL>5,0', 'SD!0,-1', 0, 1),
(19, 'Mains propres', 'Les personnages alliés doivent achever les ennemis sans leur occasionner de dommages directs. \n\nLes pièges, les glyphes, les poisons, les dommages de poussée, les renvois de dommages ainsi que les dommages infligés par des invocations peuvent être utilisé', '29,48,30,28', '(GB>0,1,0|GB>0,2,0|GB>0,4,0|GB>0,10,0|GB>0,15,0|GB>0,13,0|GB>0,17,0)&GL>14,0,e', 'Sd!0', 0, 1),
(20, 'Élémentaire', 'Lorsqu\'un combattant allié inflige des dommages dans un élément, il doit utiliser uniquement cet élément d\'attaque pendant toute la durée du combat', '483,484', 'GN>1,0&GL>5,0', 'SC=hc0,e,t', 0, 1),
(25, 'Ordonné', 'Les ennemis doivent êtres achevés dans l\'ordre décroissant de leur niveau.', '3,4,10,595,34,35,32,967,594', 'Gd>1,1&GL>5,0', 'SL>1', 0, 1),
(30, 'Les petits d\'abord', 'Le ou les combattant(s) avec le plus petit niveau doivent achever les ennemis.', '19,28,29,46,44,48', '(GN>1,1)&(GN>1,0)&GL<70,0,r&GL>20,0,r', 'SK<,hc0,e1,a', 0, 1),
(31, 'Focus', 'Lorsqu\'un ennemi est attaqué par un allié, il doit être achevé avant qu\'un autre ennemi ne soit attaqué.', '', 'GN>1,1&GL>5,0', 'SF=1', 0, 1),
(32, 'Élitiste', 'Toutes les attaques doivent être concentrées sur la cible désignée jusqu\'à ce qu\'il meure.', '3,4,10,25,594,967,595,35,34', 'GN>1,1&GL>5,0', 'CK~!,1', 0, 1),
(33, 'Survivant', 'Aucun combattant allié ne doit mourir.', '17,49,818', '(GN>1,0)&(Gl<1)&Gv<1&GL>5,0', 'Sa=0,hc0', 0, 1),
(34, 'Imprévisible', 'Toutes les attaques des alliés doivent être concentrées sur l\'ennemi désigné à chaque début de tour global, ou lorsque l\'ennemi précédent est tué.', '3,4,10,25,32,595,967,596,814,42,35', '(GN>1,1)&(GN>1,0)&GL>5,0', 'CC=e0,m1,gk', 0, 1),
(36, 'Hardi', 'Les combattants alliés doivent finir leur tour sur une cellule adjacente à celle d\'un ennemi.', '2,481,972,40,815,488,39,37,807', 'GD<5,1&GL>5,0', 'TD<2,hc0,e1', 0, 1),
(37, 'Collant', 'Les combattants alliés doivent finir leur tour sur une cellule adjacente à celle d\'un autre combattant allié.', '2,36,39,807,965,40', 'GN>1,0&GL>5,0', 'TD<2,hc0,hc0', 0, 1),
(38, 'Blitzkrieg', 'Lorsqu\'un ennemi est attaqué, il doit être achevé avant le début de son tour de jeu.', '', 'GN>1,0&Gv<30,0&Gl>0.9&Gl<1.25&GL>89,0,e', 'SW<1,1', 0, 1),
(39, 'Misanthrope', 'Les combattants alliés ne doivent jamais finir leur tour sur une cellule adjacente à celle d\'un autre combattant allié.', '2,36,37,40', 'GN>1,0&GL>5,0', 'TD>1,hc0,hc0', 0, 1),
(40, 'Prudent', 'Les combattants alliés ne doivent jamais finir leur tour sur une cellule adjacente à celle d\'un ennemi.', '2,36,37,39,813,807,488,815,972', 'GL>5,0', 'TD>1,hc0,e1', 0, 1),
(42, 'Deux pour le prix d\'un', 'Lorsqu\'un combattant allié achève un ennemi, il doit obligatoirement achever un (et un seul) deuxième ennemi pendant son tour de jeu.', '34,46,44', '((GN=2,1)|(GN=4,1)|(GN=6,1)|(GN=8,1))&GL>5,0', 'TK~2,h0,e1,te', 0, 1),
(44, 'Partage', 'Chaque combattant allié doit avoir achevé au moins un combattant ennemi pendant le combat.', '28,29,30,42,48,46,814,596', '(((GN=2,0)&(GN>1,1))|((GN=3,0)&(GN>2,1))|((GN=4,0)&(GN>3,1))|((GN=5,0)&(GN>4,1))|((GN=6,0)&(GN>5,1))|((GN=7,0)&(GN>6,1))|((GN=8,0)&(GN>7,1)))&GL>5,0', 'Sk>0,1', 0, 1),
(45, 'Duel', 'Lorsqu\'un combattant allié attaque un ennemi, aucun autre combattant allié ne doit attaquer cet ennemi pendant toute la durée du combat.', '46', 'GN>1,0&GL>5,0', 'SO=hc0,e1,d', 0, 1),
