(862, 'Ilyzaelle', 'Vaincre le gardien de ce donjon et prouver votre bravoure.', '', 'GM>0,4967,1&Gm=d', 'Ma=1', 0, 10),
(863, 'Kanigroula', 'Vaincre le gardien de ce donjon et démontrer votre audace.', '', 'GM>0,3556,1&Gm=d', 'Ma=1', 0, 10),
(864, 'Kanigroula', 'Vaincre le gardien de ce donjon et prouver votre bravoure.', '', 'GM>0,3556,1&Gm=d', 'Ma=1', 0, 10),
(868, 'Dernier', '%1 doit être achevé en dernier.', '', 'GM>0,7197,1&Gm=d', 'Ck#7197,1', 7197, 3),
(869, 'Prudent', 'Les combattants alliés ne doivent jamais finir leur tour sur une cellule adjacente à celle d\'un ennemi.', '', 'GM>0,7197,1&Gm=d', 'TD>1,hc0,e1', 7197, 3),
(870, 'Duo', 'Vaincre tous les monstres avec 2 personnages maximum et en moins de %2 tours.', '', 'GN<3,0&GM>0,7197,1&Gm=d', 'ST<20', 7197, 3),
(872, 'Compagnons à vendre', '• Hulkrap\n• Kubitus\n• Logram\n• Rapiat\n• Mirh\n• Rekto Topi\n• Traçon\n• Flamme\n• Goutte\n• Nuage\n• Feuille\n• Ténèbre', '', '', 'Ma=0', 0, 11),
(873, 'Compagnons vagabonds', '• Piggy Paupe\n• Rapine\n• Riktus Fine-Lame\n• Haku\n• Riktus Archer\n• Riktus Baroudeur\n• Grouillot\n• Phong Huss\n• Riktus Ensorceleuse', '', '', 'Ma=0', 0, 11),
(874, 'Compagnons artisans', '• Kloug\n• Klüme\n• Grizou\n• Laikteur', '', '', 'Ma=0', 0, 11),
(875, 'Compagnons bavards', '• Kocksis\n• Grüt\n• Gobeuf\n• Karotz\n• Kalkanéus\n• Ougicle\n• Turyé', '', '', 'Ma=0', 0, 11),
(887, 'Bandits du Magik Riktus', 'Riktus fine-lame\nRiktus Archer\nRiktus Baroudeur\nRiktus ensorceleuse', '', '', 'Ma=0', 0, 11),
(888, 'Revenus d\'outre tombe', 'Kocksis\nKubitus\nKalkanéus\nHectaupe\nHichète', '', '', 'Ma=0', 0, 11),
(889, 'Chevaliers tourmentés', 'Flamme\nGoutte\nNuage\nFeuille\nTénèbre', '', '', 'Ma=0', 0, 11),
(890, 'Mini Nuits\'', 'Inferno\nStyx\nMandrin\nWill Killson', '', '', 'Ma=0', 0, 11),
(891, 'Les crados', 'Grüt\nGobeuf\nTuryé\nPiggy Paupe', '', '', 'Ma=0', 0, 11),
(892, 'Compagnons, quel est votre métier ?', 'Kloug\nKlüme\nGrizou\nLaikteur', '', '', 'Ma=0', 0, 11),
(893, 'Les z\'autres', 'Haku\nManitou Zoth\nKarotz\nGrouillot\nPhong Huss', '', '', 'Ma=0', 0, 11),
(894, 'Rats... au sens propre ou au figuré', 'Rapiat\nRapine\nOugicle\nHulkrap', '', '', 'Ma=0', 0, 11),
(895, 'Les pandaliens', 'Mirh\nRekto Topi\nTraçon\nLogram', '', '', 'Ma=0', 0, 11),
(896, 'Les héros', 'Krosmoglob\nKorbax\nMasse\nChevalier d\'Astrub', '', '', 'Ma=0', 0, 11),
(957, 'Compagnon', 'Vaincre tous les monstres avec 4 personnages minimum, dont au moins un des compagnons éligibles à la réalisation de ce succès.', '', '', 'Ma=0', 0, 11),
(961, 'Infatigable', 'Lorsqu\'un combattant allié achève un ennemi, il doit lui rester au moins la moitié des PA qu\'il possède au début de son tour (arrondi à l\'inférieur).', '', 'GL>5,0', 'TA>h,hc0,k1|TA=h,hc0,k1', 0, 1),
(962, 'Sans-cœur', 'Les combattants alliés ne peuvent jamais recevoir de soin provenant d\'alliés autres qu\'eux-mêmes.', '', 'GN>1,0&(Ge>1,2999,t0|Ge>1,2998,t0|Ge>1,3002,t0|Ge>1,3001,t0|Ge>1,3000,t0|Ge>1,81,t0|Ge>1,1109,t0|Ge>1,143,t0|Ge>1,407,t0|Ge>1,646,t0|Ge>1,108,t0)&GL>5,0', 'SO!hc0,e0,h', 0, 1),
(963, 'En ligne et contre tous', 'Les combattants alliés doivent finir leurs tours en étant placés sur la même ligne que tous les autres combattants alliés pendant toute la durée du combat.', '965', 'GN>1,0&GL>5,0', 'SP=te,l,hc0,ahc0', 0, 1),
(964, 'De la même lignée', 'Les combattants alliés doivent finir leurs tours en étant placés en ligne avec au moins un autre combattant allié pendant toute la durée du combat.', '965', 'GN>1,0&GL>5,0', 'SP=te,l,hc0,hc0', 0, 1),
(965, 'La diagonale du plein', 'Les combattants alliés doivent finir leurs tours en étant placés en diagonale avec au moins un autre combattant allié pendant toute la durée du combat.', '37,963,964', 'GN>1,0&GL>5,0', 'SP=te,d,hc0,hc0', 0, 1),
(967, 'Tueur à vue', 'Les attaques des alliés doivent être concentrées sur le combattant ennemi le plus proche de lui à chaque début de tour ou lorsque le combattant ennemi est achevé. Les invocations ont la même cible que leur invocateur.', '3,4,10,25,32,34,594', 'GL>5,1&GN>1,0', 'CO=e0,m1,t,n', 0, 1),
(968, 'Pas vu pas pris', 'Les combattants alliés ne doivent jamais finir leurs tours en ligne de vue avec un ennemi visible.', '969', 'GN>1,0&GL>50,0,e&(GB<1,3,0|GB<1,10,0|GB<1,7,0|GB<1,9,0|GB<1,2,0|GB<1,16,0|GB<1,17,0)&GN<6,1&GL>5,0', 'SV=te,hc0,e1,s0,v', 0, 1),
(969, 'En ligne de mire', 'Les combattants alliés doivent finir leurs tours en ligne de vue avec au moins un ennemi.', '968', '(GB<1,8,0|GB<1,1,0|GB<1,11,0|GB<1,18,0)&GL>5,0', 'SV=te,hc0,e1,s1,v', 0, 1),
(970, 'J\'en ai fait un pin\'s', 'Tous les ennemis doivent être achevés en étant adjacents à un obstacle. Les trous et les bords de cartes sont aussi considérés comme des obstacles.', '', 'GL>5,0', 'SK<2,hc0,e1,a,whb', 0, 1),
(971, 'Raser les murs', 'Tous les combattants alliés doivent finir leurs tours en étant adjacents à un obstacle. Les trous et les bords de cartes sont aussi considérés comme des obstacles.', '2', 'GL>5,0', 'TD<2,hc0,whb', 0, 1),
(972, 'Suis-moi je te fuis, fuis-moi je te suis', 'Lors des tours impairs, les combattants alliés doivent finir leurs tours à distance des ennemis.\nLors des tours pairs, les combattants doivent finir leurs tours au corps à corps des ennemis.', '36,40', 'GL>5,0', 'TD<2,hc0,e1,p&TD>1,hc0,e1,i', 0, 1),
(973, 'Conquérant', 'Lorsqu\'un combattant allié tue un ennemi, il doit finir son tour sur la case qu\'occupait cet ennemi.', '2', 'GL>5,0', 'TD<1,hc0,k1', 0, 1),
(974, 'Doume', 'Tous les ennemis doivent être achevés durant le même tour global.', '', 'GN>1,1&GL>5,0', 'TK~a,e0,e1,gt', 0, 1),
(975, 'Légitime défense', 'Un combattant allié ne peut attaquer un ennemi que si cet ennemi lui a déjà infligé des dommages.', '', 'GL>5,0', 'SB=hc0,m1', 0, 1),
(976, 'Martyr', 'Le combattant allié désigné est le seul à pouvoir recevoir des dommages pendant toute la durée du combat. S\'il meurt, le challenge échoue.', '17', 'GN>1,0&GL>5,0', 'CC=e1,e0,e', 0, 1),
(977, 'Lâche mes côtes', 'Kardorim ne doit jamais finir son tour au corps à corps d\'un combattant. \nLes Kardoribs ne doivent pas subir de dommages, ni être poussés.', '', 'GM>0,4051,1&Gm=d', 'Ma=1', 4051, 3),
(978, 'Mauvaise graine', 'Les invocations du Tournesol Affamé doivent systématiquement être achevées avant le début de leur deuxième tour de jeu.', '', 'GM>0,799,1&Gm=d', 'Ma=1', 799, 3),
(979, 'Passer l\'éponge', 'À partir du tour 2, Mob l\'éponge doit être poussé ou attiré au moins une fois à chaque tour global.', '', 'GM>0,928,1&Gm=d', 'Ma=1', 928, 3),
(980, 'Un Mulou dans la Bergerie', 'Les ennemis ne doivent pas recevoir de soin.', '', 'GM>0,147,1&Gm=d', 'Ma=1', 147, 3),
(981, 'Empêtrement d\'esprit entêtant', 'Aucun Ashi-magari ne doit être achevés pendant toute la durée du combat.', '', 'GM>0,2975,1&Gm=d', 'Ma=1', 2975, 3);
INSERT INTO `challenges` (`Id`, `Name`, `Description`, `IncompatiblesChallenges`, `ActivationCriterion`, `CompletionCriterion`, `TargetMonsterId`, `CategoryId`) VALUES
(982, 'Dorée, mi fa sol', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,797,1&Gm=d', 'Ma=1', 797, 3),
(983, 'Désillusion', 'Aucune illusion du Chafer Rōnin ne doit être présente au début de son tour.', '', 'GM>0,3238,1&Gm=d', 'Ma=1', 3238, 3),
(984, 'Bécotam', 'Lorsque les combattants alliés infligent des dommages aux ennemis, ils doivent être en ligne de ces derniers.', '', 'GM>0,800,1&Gm=d', 'Ma=1', 800, 3),
(985, 'La ligne interdite', 'Les alliés ne doivent terminer leur tour ni en ligne d\'un ennemi, ni en ligne d\'un autre allié.', '', 'GM>0,3945,1&Gm=d', 'Ma=1', 3945, 3),
(986, 'Dirige mais mal rédige', 'À partir du tour 2, les combattants ennemis doivent commencer leur tour sur une cellule adjacente à celle d\'un allié ou d\'un ennemi.', '', 'GM>0,6903,1&Gm=d', 'Ma=1', 6903, 3),
(987, 'Tombés sous le charme', 'Les ennemis ne doivent être achevés que par des combattants dans l\'état insoignable.', '', 'GM>0,792,1&Gm=d', 'Ma=1', 792, 3),
(988, 'Ouverture facile', 'Les ennemis doivent être achevés uniquement lorsque le Coffre des Forgerons possède moins de 50 % de ses points de vie. Le challenge échoue si le Coffre des Forgerons n\'est pas achevé en dernier.', '', 'GM>0,252,1&Gm=d', 'Ma=1', 252, 3),
(989, 'Collé-serré', 'À partir du tour global 2, les combattants doivent commencer leur tour au corps à corps du corailleur magistral. Le challenge échoue si le Corailleur Magistral n\'est pas achevé en dernier.', '', 'GM>0,1027,1&Gm=d', 'Ma=1', 1027, 3),
(990, 'Kwakwa ? Kwapoussée !', 'Les ennemis ne doivent pas subir de dommages de poussée.', '', 'GM>0,2995,1&Gm=d', 'Ma=1', 2995, 3),
(991, 'Enlisement larvaire', 'Les combattants ne doivent infliger des dégats qu\'au Shin Larve lorsqu\'ils sont sous l\'effet du sort Enlisement', '', 'GM>0,457,1&Gm=d', 'Ma=1', 457, 3),
(992, 'Vigilance forestière', 'Les alliés ne doivent pas cumuler plus de deux faiblesses élémentaires différentes au début de leur tour.', '', 'GM>0,7197,1&Gm=d', 'Ma=1', 7197, 3),
(993, 'Touche pas à mon blop', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,1184,1&Gm=d', 'Ma=1', 1184, 3),
(994, 'Touche pas à mon blop', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,1187,1&Gm=d', 'Ma=1', 1187, 3),
(995, 'Touche pas à mon blop', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,1186,1&Gm=d', 'Ma=1', 1186, 3),
(996, 'Touche pas à mon blop', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,1185,1&Gm=d', 'Ma=1', 1185, 3),
(997, 'Rituel de survie', 'Lorsqu\'un ennemi subit des dommages, il doit être sur une cellule adjacente à celle d\'au moins une entité, qu\'elle soit alliée ou ennemie.', '', 'GM>0,2960,1&Gm=d', 'Ma=1', 2960, 3),
(998, 'Privé de dessert', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,430,1&Gm=d', 'Ma=1', 430, 3),
(999, 'Privé de dessert', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,58,1&Gm=d', 'Ma=1', 58, 3),
(1000, 'Privé de dessert', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,85,1&Gm=d', 'Ma=1', 85, 3),
(1001, 'Privé de dessert', 'Les invocations ennemies ne doivent subir aucun dommage.', '', 'GM>0,86,1&Gm=d', 'Ma=1', 86, 3),
(1002, 'Mené à la cawotte', 'Lorsqu\'une Cawotte Woyale est présente, seul le Wa Wabbit doit recevoir des dommages.', '', 'GM>0,180,1&Gm=d', 'Ma=1', 180, 3),
(1003, 'De véritables craqu\'', 'Aucun combattant ennemi ne doit subir des dégâts lorsque des invocations ennemies sont en vie.', '', 'GM>0,669,1&Gm=d', 'Ma=1', 669, 3),
(1004, 'Tonneaux truands', 'Tous les ennemis doivent subir au moins une fois les effets d\'un tonneau de pirate.', '', 'GM>0,1051,1&Gm=d', 'Ma=1', 1051, 3),
(1005, 'Laboratoire de curiosité', 'Les combattants ne doivent avoir aucun allié situé à 3 PO ou moins d\'eux lorsqu\'ils infligent des dommages à un ennemi.', '', 'GM>0,3100,1&Gm=d', 'Ma=1', 3100, 3),
(1006, 'Sortir de sa coquille', 'Les ennemis ne doivent être achevés que lorsqu\'au moins l\'un d\'eux se trouve dans l\'état Intrépide (évolution maximale).', '', 'GM>0,5823,1&Gm=d', 'Ma=1', 5823, 3),
(1007, 'À portée de dard', 'Mantiscore ne doit pas recevoir de dégât à distance.', '', 'GM>0,4621,1&Gm=d', 'Ma=1', 4621, 3),
(1008, 'A fond les boulons', 'Les alliés ne doivent pas recevoir de dommages de poussée.', '', 'GM>0,3460,1&Gm=d', 'Ma=1', 3460, 3),
(1009, 'Saute-pirate', 'Lorsque le Chouque échange de place avec un de ses alliés, ce dernier doit être achevé en moins de deux tours.', '', 'GM>0,230,1&Gm=d', 'Ma=1', 230, 3),
(1010, 'Distance respectueuse', 'Les combattants ne doivent avoir aucun ennemi situé à 3 PO ou moins d\'eux lorsqu\'ils infligent des dommages à un ennemi.', '', 'GM>0,173,1&Gm=d', 'Ma=1', 173, 3),
(1011, 'Chacun son tour de magie', 'Lorsqu\'un ennemi déplace un allié, cet ennemi doit être lui-même être déplacé par un allié avant le début de son prochain tour.', '', 'GM>0,4860,1&Gm=d', 'Ma=1', 4860, 3),
(1012, 'On ne peut la Nyée', 'Lorsque la Reine Nyée invoque un Oeuf de Trégénaire, celui-ci doit être achevé avant le début de son prochain tour.', '', 'GM>0,3996,1&Gm=d', 'Ma=1', 3996, 3),
(1013, 'Faut pas pousser les cochons dans la confiture d\'orties', 'Les alliés ne doivent pas recevoir de dommages de poussée.', '', 'GM>0,113,1&Gm=d', 'Ma=1', 113, 3),
(1014, 'À la cool', 'Aucun allié ne doit être transformé en boufcool.', '', 'GM>0,670,1&Gm=d', 'Ma=1', 670, 3),
(1015, 'Meulou y es-tu ?', 'Les ennemis ne peuvent pas subir plus de trois attaques par tour de la part du même allié.', '', 'GM>0,232,1&Gm=d', 'Ma=1', 232, 3),
(1016, 'Les yeux aussi gros que le ventre', 'Les ennemis doivent avoir au moins un allié en ligne de vue au début de leur tour.', '', 'GM>0,5819,1&Gm=d', 'Ma=1', 5819, 3),
(1017, 'Échapper au fisk', 'Tuer %1 en dernier.', '', 'GM>0,3652,1&Gm=d', 'Ma=1', 3652, 3),
(1018, 'Animal totem', 'Les totems de Darkli Moon ne doivent jamais perdre de points de vie.', '', 'GM>0,226,1&Gm=d', 'Ma=1', 226, 3),
(1019, 'Spectacle de marionnettes', 'Les marionnettes doivent être achevées dans l\'ordre dans lequel elles ont été invoquées.', '', 'GM>0,3476,1&Gm=d', 'Ma=1', 3476, 3),
(1020, 'Ras le boule', 'Il ne doit jamais y avoir plus de 2 rasbouls mineurs sur le terrain au début du tour de Silf le Rasboul Majeur.', '', 'GM>0,1071,1&Gm=d', 'Ma=1', 1071, 3),
(1021, 'La taille du rat', 'Chaque ennemi doit subir des dégâts au moins une fois entre chacun de ses tours.', '', 'GM>0,940,1&Gm=d', 'Ma=1', 940, 3),
(1022, 'Rat-trapage', 'Le Rat Noir ne doit pas subir de dommages avant que tous les autres ennemis soient achevés.', '', 'GM>0,939,1&Gm=d', 'Ma=1', 939, 3),
(1023, 'Maître Corbac sur un arbre perché', 'À la fin du tour d\'un combattant allié, un ennemi doit se situer à 5PO ou moins de lui.', '', 'GM>0,289,1&Gm=d', 'Ma=1', 289, 3),
(1024, 'On lui pèlera le bourgeon', 'Un allié ne doit pas subir plus d\'une fois l\'explosion d\'un Bourgeon de Damadrya.', '', 'GM>0,6326,1&Gm=d', 'Ma=1', 6326, 3),
(1025, 'Sac à pupuces', 'Chaque pupuce invoquée par le Pounicheur ne doit pas changer d\'état plus d\'une fois par tour global.', '', 'GM>0,4278,1&Gm=d', 'Ma=1', 4278, 3),
(1026, 'Poursuite royale', 'Chaque monstre ne doit pas utiliser de PM au moins une fois dans tout le combat avant d\'être achevé.', '', 'GM>0,382,1&Gm=d', 'Ma=1', 382, 3),
(1027, 'Les fans et les enfants d\'abord', 'Les poupées doivent être achevées dans l\'ordre définit. Au début du combat, l\'une d\'elle est choisie, puis détermine la prochaine à sa mort. Toutes les Poupées doivent être achevées avant que le Skeunk ne puisse subir de dégât.', '', 'GM>0,780,1&Gm=d', 'Ma=1', 780, 3),
(1028, 'Garde emplumée', 'Le Minotoror ne doit pas subir de dommages si au moins un de ses tofus est présent sur le terrain.', '', 'GM>0,121,1&Gm=d', 'Ma=1', 121, 3),
(1029, 'L\'heure tourne', 'Les ennemis ne doivent pas infliger de dommages aux autres ennemis.', '', 'GM>0,3852,1&Gm=d', 'Ma=1', 3852, 3),
(1030, 'Touche pas à mes blops', 'Toutes les attaques doivent être concentrées sur le Blop Multicolore Royal jusqu\'à ce qu\'il meure.', '', 'GM>0,1188,1&Gm=d', 'CK#1188,1&Ma=1', 1188, 3),
(1031, 'En cassant des œufs', 'Les coquilles invoquées doivent être achevés avant le début de leur troisième tour et aucun allié ne doit subir de dommage de leur explosion.', '', 'GM>0,854,1&Gm=d', 'Ma=1', 854, 3),
(1032, 'Parcimonie royale', 'Durant son tour de jeu, si un allié déplace un ennemi, il ne doit plus infliger de dommages à cet ennemi pendant le reste de son tour.', '', 'GM>0,2854,1&Gm=d', 'Ma=1', 2854, 3),
(1033, 'Sortie de ring', 'Les alliés doivent terminer leur tour sur leur cellule de début de combat.', '', 'GM>0,3753,1&Gm=d', 'Ma=1', 3753, 3),
(1034, 'Guerilla', 'Les alliés ne doivent pas infliger de dommages à un autre allié par le biais du sort Guerillero', '', 'GM>0,4609,1&Gm=d&GN>1,0', 'Ma=1', 4609, 3),
(1035, 'Truchement', 'Les ennemis doivent être déplacés avant de subir des dommages. Un ennemi déplacé est considéré comme tel jusqu\'au début de son prochain tour.', '', 'GM>0,3618,1&Gm=d', 'Ma=1', 3618, 3),
(1036, 'Le jeu de la Dame', 'Les Bombombres ne doivent subir aucun dommages.', '', 'GM>0,6256,1&Gm=d', 'Ma=1', 6256, 3),
(1037, 'Enchaînemou', 'Les alliés doivent terminer leur tour en ligne d\'un ennemi.', '', 'GM>0,257,1&Gm=d', 'Ma=1', 257, 3),
(1038, 'Se faire des kouïs en or', 'Un ennemi ne doit pas être déplacé plus d\'une fois par tour global.', '', 'GM>0,6218,1&Gm=d', 'Ma=1', 6218, 3),
(1039, 'Prendre racine', 'Les ennemis ne doivent ni être déplacés (téléportation, attirance, poussée), ni subir de tentative de retrait PM.', '', 'GM>0,1072,1&Gm=d', 'Ma=1', 1072, 3),
(1040, 'Privilège royal', 'Chaque début de tour, le Mansot Royal désigne un combattant. Seul le combattant désigné peut recevoir des soins.', '', 'GM>0,2848,1&Gm=d&GN>1,0', 'Ma=1', 2848, 3),
(1041, 'Vents contraires', 'Les ennemis qui maitrisent le souffle du Wukin ne doivent subir que des dommages en mêlée et les ennemis qui maitrisent le souffle du Wukang ne doivent subir que des dommages à distance.', '', 'GM>0,6212,1&Gm=d', 'Ma=1', 6212, 3),
(1042, 'Raviver la flamme', 'Aucun feu ne doit se rallumer, une fois éteint.', '', 'GM>0,6249,1&Gm=d', 'Ma=1', 6249, 3),
(1043, 'Pizwa quatre couleurs', 'Aucun allié ne doit subir les effets du sort Kawabunga.', '', 'GM>0,943,1&Gm=d', 'Ma=1', 943, 3),
(1044, 'Hamrack\'n roll', 'Les alliés ne doivent pas subir de dommages provenant d\'un Hamrack.', '', 'GM>0,2877,1&Gm=d', 'Ma=1', 2877, 3),
(1045, 'Diagonale du vide', 'Les alliés ne doivent pas terminer leur tour en étant placés en diagonale d\'un ennemi ou d\'un allié.', '', 'GM>0,3651,1&Gm=d', 'Ma=1', 3651, 3),
(1046, 'Hellémentaire', 'Les combattants doivent obligatoirement infliger des dommages à Hell Mina correspondant à l\'état élémentaire attribué qu\'elle attribue à chaque tour.', '', 'GM>0,107,1&Gm=d', 'Ma=1', 107, 3),
(1047, 'Une paire d\'impairs', 'Chaque ennemi doit subir les effets du glyphe déclenché par le Disciple du Kimbo avant de recevoir des dégâts.', '', 'GM>0,1045,1&Gm=d', 'Ma=1', 1045, 3),
(1048, 'Tofu-phobie', 'Aucun combattant ne doit subir l\'effet du sort Destinos.', '', 'GM>0,827,1&Gm=d', 'Ma=1', 827, 3),
(1049, 'À son hypogée', 'Les ennemis ne doivent être ni attirés, ni poussés.', '', 'GM>0,2924,1&Gm=d', 'Ma=1', 2924, 3),
(1050, 'Crocs à crocs', 'Les ennemis ne doivent subir que des dommages en mêlée.', '', 'GM>0,3556,1&Gm=d', 'Ma=1', 3556, 3),
(1051, 'Duel et pique', 'Les alliés ne doivent pas attaquer plusieurs fois dans le même tour un même ennemi.', '', 'GM>0,4264,1&Gm=d', 'Ma=1', 4264, 3),
(1052, 'Une lanterne dans la nuit', 'Aucun ennemi ne doit subir les effets du sort \"Lanterne des Spiritueurs\" à l\'exception du Shogun Tofugawa.', '', 'GM>0,6388,1&Gm=d', 'Ma=1', 6388, 3),
(1053, 'Autonomie givrée', 'Les alliés doivent terminer leur tour à plus de 4 PO de tous les autres alliés.', '', 'GM>0,2967,1&Gm=d&GN>1,0', 'Ma=1', 2967, 3),
(1054, 'Émancipation maternelle', 'Les alliés ne doivent jamais terminer en ligne d\'un ennemi.', '', 'GM>0,3234,1&Gm=d', 'Ma=1', 3234, 3),
(1055, 'C\'est très vague !', 'Tous les ennemis d\'une vague doivent être achevés avant l\'arrivée d\'une nouvelle vague.', '', 'GM>0,3849,1&Gm=d', 'Ma=1', 3849, 3),
(1056, 'On ne touche pas', 'Les combattants doivent terminer leur tour en diagonale d\'un ennemi.', '', 'GM>0,4726,1&Gm=d', 'Ma=1', 4726, 3),
(1057, 'La lumière ne fut jamais', 'Aucun allié ne doit utiliser le sort Lanterne des Spiritueurs.', '', 'GM>0,6394,1&Gm=d', 'Ma=1', 6394, 3),
(1058, 'Baston équitable', 'Les ennemis ne doivent subir ni retrait PM, ni retrait PA, ni retrait PO, ni tentative de déplacement.', '', 'GM>0,478,1&Gm=d', 'Ma=1', 478, 3),
(1059, 'Mycologie', 'Les combattants ne doivent pas terminer leur tour en ligne ou en diagonale d\'un ennemi.', '', 'GM>0,1159,1&Gm=d', 'Ma=1', 1159, 3),
(1060, 'Un projet tentaculaire', 'Les combattants ne doivent pas terminer leur tour en ligne d\'un allié.', '', 'GM>0,423,1&Gm=d&GN>1,0', 'Ma=1', 423, 3),
(1061, 'Pas dans mes pattes', 'Les combattants doivent terminer leur tour à plus de 3 PO d\'un allié.', '', 'GM>0,2968,1&Gm=d&GN>1,0', 'Ma=1', 2968, 3),
(1062, 'Relation toxique', 'Tuer %1 en dernier.', '', 'GM>0,3752,1&Gm=d', 'Ma=1', 3752, 3),
(1063, 'Alliés passés au futur', 'Les alliés ne doivent pas recevoir de soin.', '', 'GM>0,2986,1&Gm=d', 'Ma=1', 2986, 3),
(1064, 'Complaisance gloursonne', 'Les ennemis ne doivent subir ni retrait PM, ni retrait PA, ni retrait PO, ni tentative de déplacement par les alliés.', '', 'GM>0,2864,1&Gm=d', 'Ma=1', 2864, 3),
(1065, 'On voulait l\'autre', 'Les ennemis dans l\'état Zombi ne doivent pas être déplacés.', '', 'GM>0,2942,1&Gm=d', 'Ma=1', 2942, 3),
(1066, 'Jeux d\'ombres', 'Les combattants ennemis ne doivent subir que des dommages de mêlée.', '', 'GM>0,3564,1&Gm=d', 'Ma=1', 3564, 3),
(1067, 'Nos amies les bêtes', 'Aucune invocation alliée ne doit être achevée par un ennemi.', '', 'GM>0,4803,1&Gm=d', 'Ma=1', 4803, 3),
(1068, 'Antioxydant', 'Aucun ennemi ne doit entrer dans l\'état Nimpatience V.', '', 'GM>0,7219,1&Gm=d', 'Ma=1', 7219, 3),
(1069, 'Brikolère', 'Les ennemis dans l\'état Zombi ne doivent infliger de dommages ni aux alliés ni aux ennemis.', '', 'GM>0,3409,1&Gm=d', 'Ma=1', 3409, 3),
(1070, 'Dur à cuir', 'Aucun allié ne doit entrer dans l\'état Pacifiste.', '', 'GM>0,3384,1&Gm=d', 'Ma=1', 3384, 3),
(1071, 'Attention, sol glissant', 'Aucun allié ne doit subir de dommages de poussée.', '', 'GM>0,3391,1&Gm=d', 'Ma=1', 3391, 3),
(1072, 'Alchi-pludent', 'Aucun allié ne doit entrer dans l\'état Pacifiste.', '', 'GM>0,3397,1&Gm=d', 'Ma=1', 3397, 3),
(1073, 'L\'échec n\'est pas une option', 'Les ennemis ne doivent pas subir de dommages de mêlée.', '', 'GM>0,3416,1&Gm=d', 'Ma=1', 3416, 3),
(1074, 'Voyez, il y a du monde', 'Chaque combattant doit commencer ou terminer son tour en ligne d\'un ennemi.', '', 'GM>0,3534,1&Gm=d', 'Ma=1', 3534, 3),
(1075, 'Pingrerie', 'Lorsqu\'un allié inflige des dommages, il doit se situer en ligne ou en diagonale de sa cible.', '', 'GM>0,3648,1&Gm=d', 'Ma=1', 3648, 3),
(1076, 'La vie est une chausse-trappe', 'Les alliés ne doivent pas être soignés par le biais des Bonbombes bleues.', '', 'GM>0,3726,1&Gm=d', 'Ma=1', 3726, 3),
(1077, 'Qui dit boum ?', 'La Malamibe doit toujours être achevée avant le début de son prochain tour.', '', 'GM>0,3828,1&Gm=d', 'Ma=1', 3828, 3),
(1078, 'Heure de la mort', 'Tous les ennemis doivent être achevés à la même heure.', '', 'GM>0,3835,1&Gm=d', 'Ma=1', 3835, 3),
(1079, 'Les bons comptes font les bons ennemis.', 'Les combattants doivent toujours terminer leur tour sur une cellule correspondant au numéro de leur cellule de début de combat.', '', 'GM>0,4263,1&Gm=d', 'Ma=1', 4263, 3),
(1080, 'Parfum de mutinerie', 'Les combattants doivent terminer leur tour en ligne d\'un combattant.', '', 'GM>0,4460,1&Gm=d&GN>1,0', 'Ma=1', 4460, 3),
(1081, 'Chaises musicales', 'Après son premier tour, un ennemi doit échanger de place avec un allié au moins une fois entre chacun de ses tours.', '', 'GM>0,4453,1&Gm=d', 'Ma=1', 4453, 3),
(1082, 'Chasse aux coquillages', 'Un coquillage ne peut subir des dommages que de la part du combattant auquel il est lié.', '', 'GM>0,4444,1&Gm=d', 'Ma=1', 4444, 3),
(1083, 'Système pyramidal', 'Un ennemi ne doit pas être ressuscité plus de deux fois.', '', 'GM>0,4744,1&Gm=d', 'Ma=1', 4744, 3),
(1084, 'Qu\'est-ce qu\'elle a ma goule ?', 'Chaque combattant doit être goulifié au moins une fois au cours du combat.', '', 'GM>0,4882,1&Gm=d', 'Ma=1', 4882, 3),
(1085, 'Aux portes d\'Externam', 'Ilyzaelle doit être achevée avant l\'apparition de la troisième vague de monstres.', '', 'GM>0,4967,1&Gm=d', 'Ma=1', 4967, 3),
(1086, 'La mort sait attendre', 'Aucun ennemi ne doit entrer dans l\'état Necronyx avant la mort de Béthel', '', 'GM>0,5110,1&Gm=d', 'Ma=1', 5110, 3),
(1087, 'La mort sait attendre', 'Aucun ennemi ne doit entrer dans l\'état Necronyx avant la mort de Solar.', '', 'GM>0,5100,1&Gm=d', 'Ma=1', 5100, 3),
(1088, 'Manque de nimpatience', 'Les ennemis ne doivent être achevés que lorsqu\'ils se trouvent dans l\'état Nimpatience III.', '', 'GM>0,5319,1&Gm=d', 'Ma=1', 5319, 3),
(1089, 'Lunatique', 'Chaque ennemi doit être achevé soit durant la phase de Nouvelle Lune, soit durant la phase de Pleine Lune. La Lunorbe ne doit jamais être utilisée pour accélérer le rythme du cycle lunaire.', '', 'GM>0,5806,1&Gm=d', 'Ma=1', 5806, 3),
(1090, 'Immunité collective', 'Seuls les combattants alliés sans aucune maladie peuvent occasionner des dommages aux ennemis.', '', 'GM>0,6026,1&Gm=d', 'Ma=1', 6026, 3),
(1091, 'Bain de foule', 'Les alliés ne doivent pas achever les Armécréantes invoquées.', '', 'GM>0,5955,1&Gm=d', 'Ma=1', 5955, 3),
(1092, 'Abjecte opulence', 'Misère doit être achevée en première, elle doit également rentrer dans l\'état Collecte au moins une fois par tour.', '', 'GM>0,5990,1&Gm=d', 'Ma=1', 5990, 3),
(1093, 'Arsenal total', 'Aucune arme de Guerre ne doit être achevée ou déplacée par un allié.', '', 'GM>0,6014,1&Gm=d', 'Ma=1', 6014, 3),
(1094, 'Régence d\'encre', 'L\'invocation \"Reine Amirukam\" doit être achevée par un allié avant que le Roi Imagami ne sorte de sa phase Lotus.', '', 'GM>0,6472,1&Gm=d', 'Ma=1', 6472, 3),
(1095, 'Régence de papier', 'L\'invocation \"Roi Imagami\" doit être achevée par un allié avant que la Reine Amirukam ne sorte de sa phase Lotus.', '', 'GM>0,6478,1&Gm=d', 'Ma=1', 6478, 3),
(1096, 'Gros Bras', 'Les ennemis doivent être achevés uniquement à l\'aide des bras démoniaques.', '', 'GM>0,6654,1&Gm=d', 'Ma=1', 6654, 3),
(1097, 'Jusqu\'à l\'Aurore', 'Les alliés ne doivent pas achever le Bonraphin et le Brâklotin.', '', 'GM>0,6792,1&Gm=d', 'Ma=1', 6792, 3),
(1098, 'Cible facile', 'À la fin de son tour, Belladone désigne un combattant allié. Ce combattant doit se trouver en ligne de vue de Belladone au début du prochain tour de cette dernière. Si l\'allié meurt alors qu\'il est désigné, le challenge échoue.', '', 'GM>0,7210,1&Gm=d', 'Ma=1', 7210, 3);
